<?php require_once __DIR__.'/auth.php'; $title='One Day Tours'; include 'admin-head.php'; include 'sidebar.php'; include 'topbar.php'; ?><main class="main"><?php $items=read_data('onedaytours');if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0);if(($_POST['action']??'')==='delete'){$items=array_values(array_filter($items,fn($x)=>(int)$x['id']!==$id));write_data('onedaytours',$items);redirect('onedaytour.php');}$image=trim($_POST['image']??'');if($u=save_uploaded_image('image_file'))$image=$u;if(!$image)$image='srilanka.jpg';$r=['id'=>$id?:next_id($items),'title'=>trim($_POST['title']??''),'province'=>trim($_POST['province']??''),'image'=>$image,'description'=>trim($_POST['description']??''),'price'=>trim($_POST['price']??''),'highlights'=>array_values(array_filter(array_map('trim',explode(',',$_POST['highlights']??''))))];if($id){foreach($items as &$x)if((int)$x['id']===$id)$x=$r;unset($x);}else$items[]=$r;write_data('onedaytours',$items);redirect('onedaytour.php');}$edit=null;if(isset($_GET['edit']))foreach($items as $x)if((int)$x['id']===(int)$_GET['edit'])$edit=$x;?>
<div class="row g-4"><div class="col-lg-5"><div class="card shadow-sm p-4"><h5 class="fw-bold"><?= $edit?'Edit':'Add' ?> One Day Tour</h5><form method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><label class="form-label mt-3">Title *</label><input name="title" class="form-control" value="<?=e($edit['title']??'')?>" required><label class="form-label mt-3">Province</label><select name="province" class="form-select"><option value="">Select</option><?php foreach(['Western Province','Central Province','Southern Province','Northern Province','Eastern Province','Uva Province','Sabaragamuwa Province','North Central Province','North Western Province'] as $p): ?><option <?=$p===($edit['province']??'')?'selected':''?>><?=$p?></option><?php endforeach;?></select><label class="form-label mt-3">Price (LKR)</label><input name="price" class="form-control" value="<?=e($edit['price']??'')?>"><label class="form-label mt-3">Description</label><textarea name="description" class="form-control" rows="4"><?=e($edit['description']??'')?></textarea><label class="form-label mt-3">Highlights (comma separated)</label><textarea name="highlights" class="form-control" rows="3"><?=e(implode(', ',$edit['highlights']??[]))?></textarea><label class="form-label mt-3">Image URL / filename</label><input name="image" class="form-control" value="<?=e($edit['image']??'')?>"><input type="file" name="image_file" class="form-control mt-2" accept="image/*"><button class="btn btn-success w-100 mt-4">Save Tour</button></form></div></div><div class="col-lg-7"><div class="row g-3"><?php foreach($items as $x): ?><div class="col-md-6"><div class="card shadow-sm h-100"><img src="<?=e(admin_asset($x['image']))?>" style="height:170px;object-fit:cover"><div class="card-body"><h6 class="fw-bold"><?=e($x['title'])?></h6><small class="text-muted"><?=e($x['province'])?></small><p class="small mt-2"><?=e($x['description'])?></p><a href="?edit=<?=$x['id']?>" class="btn btn-sm btn-outline-primary">Edit</a><form class="d-inline" method="post" onsubmit="return confirm('Delete tour?')"><input type="hidden" name="id" value="<?=$x['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div></div></div><?php endforeach;?></div></div></div><?php include 'admin-foot.php'; ?>